import { DieKind, DieShape, Vec3, dot, faceCentroid, faceNormal, getShape, normalize } from './geometry';

/**
 * Layout of the number texture atlas (assets/dice/atlas.png). The PNG is
 * generated by scripts/gen-dice-atlas.ts from this same file, so the renderer
 * and the image can never disagree about where a face's number sits.
 */

export const CELL = 128;
export const COLS = 10;
export const KINDS: DieKind[] = ['d4', 'd6', 'd8', 'd10', 'd10p', 'd12', 'd20'];

/** Label height as a fraction of the cell, tuned per face shape. */
export const FONT_SCALE: Record<DieKind, number> = {
  d4: 0.25,
  d6: 0.46,
  d8: 0.34,
  d10: 0.34,
  d10p: 0.28,
  d12: 0.36,
  d20: 0.3,
};

/** How much of the cell the face's circumscribed circle fills. */
const FILL = 0.94;

export interface Cell {
  kind: DieKind;
  face: number;
  index: number;
}

export const CELLS: Cell[] = KINDS.flatMap((kind) => getShape(kind).faces.map((_, face) => ({ kind, face })))
  .map((c, index) => ({ ...c, index }));

export const ROWS = Math.ceil(CELLS.length / COLS);
export const ATLAS_W = COLS * CELL;
export const ATLAS_H = ROWS * CELL;

export function cellIndex(kind: DieKind, face: number): number {
  return CELLS.find((c) => c.kind === kind && c.face === face)!.index;
}

/** Face vertex positions in the cell's own [0,1]² space, y up, label centred at (0.5, 0.5). */
export function faceUVs(shape: DieShape, face: number): [number, number][] {
  const f = shape.faces[face];
  const c = faceCentroid(shape, f);
  const n = faceNormal(shape, f);
  const upV = shape.vertices[f[shape.faceUpVertex[face]]];
  const up = normalize([upV[0] - c[0], upV[1] - c[1], upV[2] - c[2]]);
  const right: Vec3 = [up[1] * n[2] - up[2] * n[1], up[2] * n[0] - up[0] * n[2], up[0] * n[1] - up[1] * n[0]];
  const pts = f.map((i) => {
    const p: Vec3 = [shape.vertices[i][0] - c[0], shape.vertices[i][1] - c[1], shape.vertices[i][2] - c[2]];
    return [dot(p, right), dot(p, up)] as [number, number];
  });
  const r = Math.max(...pts.map(([x, y]) => Math.hypot(x, y)));
  return pts.map(([x, y]) => [0.5 + (x / r) * 0.5 * FILL, 0.5 + (y / r) * 0.5 * FILL]);
}

/** Maps a point in a cell's [0,1]² space to atlas UV (three.js convention, v up). */
export function atlasUV(index: number, [u, v]: [number, number]): [number, number] {
  const col = index % COLS;
  const row = Math.floor(index / COLS);
  return [(col + u) / COLS, 1 - (row + 1 - v) / ROWS];
}
